set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
import json,base64,hashlib
from pathlib import Path
data=json.loads('{"rag/eval/reports/trip_budget_v1_mock.json": "", "rag/eval/reports/trip_budget_v1_mock.md": "", "rag/eval/candidates/trip_budget_v1/manifest.json": ""}')
for n,b in data.items():Path(n).write_bytes(base64.b64decode(b))
m=json.loads(Path('rag/eval/candidates/trip_budget_v1/manifest.json').read_text())
for n,h in m['file_sha256'].items():assert hashlib.sha256(Path(n).read_bytes()).hexdigest()==h,n
print('All candidate evidence hashes verified')
PY
